    subject?: EntityId;
    object?: EntityId;
    predicate?: string;
    writer?: WriterId;
    staleOnly?: boolean;
    sourceRef?: string;
  }, page?: { limit?: number; cursor?: string }): Promise<Page<FactView>>;

