    from: EntityId;
    predicates?: string[];       // default: all
    direction?: 'out' | 'in' | 'both';   // default: 'out'
    depth?: 1 | 2 | 3;           // default: 1
    limit?: number;              // default 50, max 500
  }): Promise<{ paths: Array<{ facts: FactView[]; end: Entity }>; truncated: boolean }>;

